/**
 * Pure lookup/formatting for the per-locale catalogs generated by
 * scripts/build-i18n-catalogs.mjs. Chunk loading lives in ./catalog-loader.
 */

export interface CatalogObject {
  [key: string]: CatalogNode;
}

export type CatalogNode = string | CatalogObject;
export type Catalog = CatalogObject;
export type MessageParams = Record<string, unknown> & {
  defaultValue?: unknown;
};

const PLACEHOLDER = /\{\{\s*([\w.-]+)\s*\}\}/g;

const pluralRulesCache = new Map<string, Intl.PluralRules>();

export function pluralCategory(locale: string, count: number): string {
  let rules = pluralRulesCache.get(locale);

  if (!rules) {
    try {
      rules = new Intl.PluralRules(locale);
    } catch {
      rules = new Intl.PluralRules("en");
    }

    pluralRulesCache.set(locale, rules);
  }

  return rules.select(count);
}

function isRecord(value: unknown): value is CatalogObject {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function formatMessage(template: string, params?: MessageParams): string {
  if (!params || !template.includes("{{")) return template;

  return template.replace(PLACEHOLDER, (match, name: string) => {
    const value = params[name];

    return value === undefined || value === null ? match : String(value);
  });
}

/** Walks a dot path and returns the containing object plus the leaf value. */
function resolvePath(
  catalog: Catalog,
  key: string,
): { parent?: CatalogObject; leaf?: string; value?: CatalogNode } {
  const parts = key.split(".");

  if (parts.length === 1) {
    return { parent: catalog, leaf: parts[0], value: catalog[parts[0]] };
  }

  let node: CatalogNode = catalog;

  for (let index = 0; index < parts.length - 1; index += 1) {
    if (!isRecord(node)) return {};

    const next: CatalogNode | undefined = node[parts[index]];

    if (next === undefined) return {};

    node = next;
  }

  if (!isRecord(node)) return {};

  const leaf = parts[parts.length - 1];

  return { parent: node, leaf, value: node[leaf] };
}

/**
 * Resolves one message key against a catalog.
 * Returns undefined when the key (or its plural vari) does not exist.
 */
export function translate(
  catalog: Catalog | undefined,
  locale: string,
  key: string,
  params?: MessageParams,
): string | undefined {
  if (!catalog) return undefined;

  const { parent, leaf, value } = resolvePath(catalog, key);

  if (!parent || !leaf) return undefined;

  const count = params?.count;

  if (typeof count === "number" && Number.isFinite(count)) {
    const plural = parent[`${leaf}_${pluralCategory(locale, count)}`] ?? parent[`${leaf}_other`];

    if (typeof plural === "string") {
      return formatMessage(plural, params);
    }
  }

  return typeof value === "string" ? formatMessage(value, params) : undefined;
}

export function hasMessage(catalog: Catalog | undefined, key: string): boolean {
  if (!catalog) return false;

  return typeof resolvePath(catalog, key).value === "string";
}
